L["Follows %s and shows when it does."] = "Folgt %s und zeigt, wenn es zeigt."
L["Opens the rule editor for more options than the dropdowns have."] = "Öffnet den Regeleditor für mehr Optionen, als die Auswahlmenüs haben."
L["Can't: %s. Open the rule to change it."] = "Geht nicht: %s. Öffne die Regel, um sie zu ändern."
L["Set on the Style Overrides tab; click to open it."] = "Auf dem Reiter Stilüberschreibungen eingestellt; klicke, um ihn zu öffnen."
