-- Camera/ShoulderCam.lua
L["Toggle Shoulder Cam"] = "Schulterkamera ein-/ausschalten"
L["Moves the camera over your shoulder, using one of Blizzard's experimental camera settings."] = "Setzt die Kamera über deine Schulter, mit einer der experimentellen Kameraeinstellungen von Blizzard."
L["Why the Shoulder Cam pauses while the gamepad UI is on."] = "Warum die Schulterkamera pausiert, solange die Gamepad-Oberfläche an ist."
L["Puts the camera over your left shoulder instead of your right."] = "Setzt die Kamera über deine linke statt deine rechte Schulter."
L["How far from the middle of the screen you sit."] = "Wie weit von der Bildschirmmitte du sitzt."
L["Spot zoomed out"] = "Platz herausgezoomt"
L["Zoomed out at"] = "Herausgezoomt ab"
L["How long the camera takes to swap to your other shoulder."] = "Wie lange die Kamera zum Wechsel auf deine andere Schulter braucht."
L["How long the camera takes to go back over your shoulder after you stop targeting yourself."] = "Wie lange die Kamera braucht, um wieder über deine Schulter zu gehen, nachdem du dich nicht mehr selbst anvisierst."
L["How long the camera takes to move behind you when the Shoulder Cam pauses, and back."] = "Wie lange die Kamera braucht, um hinter dich zu gehen, wenn die Schulterkamera pausiert, und zurück."
L["The camera turns toward the NPC you talk to while their window is open."] = "Die Kamera dreht sich zum NPC, mit dem du sprichst, solange sein Fenster offen ist."
L["Where the camera turns toward who you talk to."] = "Wo sich die Kamera zu deinem Gesprächspartner dreht."
L["Escape clears your target and closes an NPC's window in one press."] = "Escape hebt dein Ziel auf und schließt das Fenster eines NPCs mit einem Druck."
L["Multi Quest fix"] = "Mehrfachquest-Korrektur"
L["Dev test: at a quest giver with more quests, Accept clears your target first."] = "Entwicklertest: Bei einem Questgeber mit mehreren Quests hebt Annehmen zuerst dein Ziel auf."
L["How long the camera takes to glide back over your shoulder after you close the window."] = "Wie lange die Kamera braucht, um nach dem Schließen des Fensters wieder über deine Schulter zu gleiten."
L["Turns to your target everywhere, in fights too."] = "Dreht sich überall zu deinem Ziel, auch im Kampf."
L["The camera turns slowly toward the enemy you target."] = "Die Kamera dreht sich langsam zum Gegner, den du anvisierst."
L["Where the camera turns toward your target."] = "Wo sich die Kamera zu deinem Ziel dreht."
L["How long the turn toward your target takes."] = "Wie lange die Drehung zu deinem Ziel dauert."
L["Enemy turn back takes"] = "Gegner-Rückdrehung dauert"
L["How long the camera takes to glide back after you clear your target."] = "Wie lange die Kamera braucht, um zurückzugleiten, nachdem du dein Ziel aufgehoben hast."
L["Glide back when you clear your target"] = "Zurückgleiten beim Aufheben des Ziels"
L["Glides back instead of snapping when you clear your target, briefly using soft enemy targeting."] = "Gleitet beim Aufheben deines Ziels zurück, statt zu springen, und nutzt dafür kurz das weiche Gegneranvisieren."
L["The ticked frames slide over to where you are on the screen."] = "Die angehakten Rahmen gleiten dorthin, wo du auf dem Bildschirm bist."
L["Your cast bar and Personal Resource Display slide along as the camera turns to your target."] = "Deine Zauberleiste und deine persönliche Ressourcenanzeige gleiten mit, während sich die Kamera zu deinem Ziel dreht."
L["Slides with you."] = "Gleitet mit dir."
L["Loss of control"] = "Kontrollverlust"
L["Floating combat text"] = "Schwebender Kampftext"
L["Raises or lowers all the ticked frames while the camera is over your shoulder."] = "Hebt oder senkt alle angehakten Rahmen, solange die Kamera über deiner Schulter ist."
L["How far the frames slide; adjust it if they land short of you or past you."] = "Wie weit die Rahmen gleiten; pass es an, wenn sie vor oder hinter dir landen."
L["This frame's own height, added to Height (all)."] = "Die eigene Höhe dieses Rahmens, zusätzlich zu Höhe (alle)."
L["Flight paths and their fly-bys."] = "Flugrouten und ihre Vorbeiflüge."

