-- Camera/ShotsPage.lua
L["Make your own version of a standing-still camera with your own sway and zoom."] = "Mach deine eigene Version einer Stillstand-Kamera mit eigenem Pendeln und Zoom."
L["Lets scenes set to a shot play it with its own sway and zoom."] = "Lässt Szenen, die auf eine Aufnahme gesetzt sind, sie mit ihrem eigenen Pendeln und Zoom abspielen."
L["Makes a new shot, starting from the cozy camera's numbers."] = "Erstellt eine neue Aufnahme, ausgehend von den Werten der gemütlichen Kamera."
L["Plays this shot now; press again or move to stop."] = "Spielt diese Aufnahme jetzt ab; erneut drücken oder bewegen zum Stoppen."
L["Deletes this shot; scenes that played it go back to its camera."] = "Löscht diese Aufnahme; Szenen, die sie abgespielt haben, nutzen wieder ihre Kamera."

-- Visions/QuestTalk.lua
L["Fade if another addon competes: it stays away while another addon has the conversation"] = "Ausblenden, wenn ein anderes Addon konkurriert: Es bleibt weg, solange ein anderes Addon das Gespräch hat"

-- Atmosphere/Tint.lua
L["Changes color through the day, from blue nights to golden evenings."] = "Wechselt die Farbe im Lauf des Tages, von blauen Nächten bis zu goldenen Abenden."
L["A mood color for the zone you're in, like pale blue in snow or sandy in deserts."] = "Eine Stimmungsfarbe für deine Zone, etwa blassblau im Schnee oder sandig in Wüsten."
L["The zone's mood and the time-of-day color together."] = "Die Stimmung der Zone und die Tageszeitfarbe zusammen."
L["My color"] = "Meine Farbe"
L["Death Vision"] = "Death Vision"
L["The world dims and goes cold while you're dead, and dark edges close in. It shows with the death camera."] = "Die Welt wird dunkler und kalt, solange du tot bist, und dunkle Ränder ziehen sich zusammen. Es erscheint mit der Todeskamera."
L["Turns Death Vision on or off."] = "Schaltet Death Vision ein oder aus."
L["How long the dark edges take to close in after you die."] = "Wie lange die dunklen Ränder nach deinem Tod brauchen, um sich zusammenzuziehen."
L["How far the dark edges reach in from each side of the screen."] = "Wie weit die dunklen Ränder von jeder Bildschirmseite hereinreichen."
L["The dark edges lift as you walk back to your body."] = "Die dunklen Ränder weichen, während du zu deinem Körper zurückläufst."
L["Shows the death screen for a few seconds (close the settings to see it)."] = "Zeigt den Todesbildschirm für ein paar Sekunden (schließ die Einstellungen, um ihn zu sehen)."
L["Also on death"] = "Auch beim Tod"
L["The game's gray screen:"] = "Der graue Bildschirm des Spiels:"
L["Graphics Boost"] = "Grafik-Boost"
L["Opens the Graphics Boost page."] = "Öffnet die Seite Grafik-Boost."

-- Atmosphere/LowHealth.lua
L["How the low-health screen edges look."] = "Wie die Bildschirmränder bei niedriger Gesundheit aussehen."
L["Turns this page's look settings on or off."] = "Schaltet die Look-Einstellungen dieser Seite ein oder aus."
L["Shows your health falling in the preview and on screen."] = "Zeigt in der Vorschau und auf dem Bildschirm, wie deine Gesundheit sinkt."
L["The look of the edges; Auto picks one for your class and spec."] = "Der Look der Ränder; Auto wählt einen für deine Klasse und Spezialisierung."
L["Undoes your changes to this theme."] = "Macht deine Änderungen an diesem Thema rückgängig."
L["Gives you this theme as text to share."] = "Gibt dir dieses Thema als Text zum Teilen."
L["Makes a blank theme of your own."] = "Erstellt ein leeres eigenes Thema."
L["Sound:"] = "Ton:"
L["The sound that plays as your health runs low."] = "Der Ton, der spielt, wenn deine Gesundheit knapp wird."
L["Ambient volume"] = "Umgebungslautstärke"
L["How loud the sound plays compared to your ambient volume."] = "Wie laut der Ton im Vergleich zu deiner Umgebungslautstärke spielt."
L["How strong the whole effect is."] = "Wie stark der ganze Effekt ist."
L["How far in from the edges the whole effect comes."] = "Wie weit der ganze Effekt von den Rändern hereinkommt."
L["How bright the art's colors are."] = "Wie hell die Farben der Grafik sind."
L["Black at 0%, the theme's color at 100%."] = "Schwarz bei 0%, die Farbe des Themas bei 100%."
L["The edges flash when a big hit lands."] = "Die Ränder blitzen auf, wenn ein großer Treffer landet."
L["Flash darkness"] = "Blitz-Dunkelheit"
L["How much darker the edges get in a flash, on top of Darkness."] = "Wie viel dunkler die Ränder bei einem Blitz werden, zusätzlich zu Dunkelheit."
L["Flash color"] = "Blitzfarbe"
L["How much a flash tints the edges."] = "Wie stark ein Blitz die Ränder tönt."
L["Flash fade"] = "Blitz-Ausblenden"
L["Seconds a flash takes to fade."] = "Sekunden, bis ein Blitz verblasst."
L["How far in it comes from the left and right sides."] = "Wie weit es von links und rechts hereinkommt."
L["The sparks that float over the edges."] = "Die Funken, die über die Ränder schweben."
L["Wisps of heat rise from the bottom of the screen as you weaken."] = "Hitzeschwaden steigen vom unteren Bildschirmrand auf, wenn du schwächer wirst."
L["A swirl that turns over the screen as you weaken."] = "Ein Wirbel, der sich über den Bildschirm dreht, wenn du schwächer wirst."
L["The kind of swirl."] = "Die Art des Wirbels."
L["How fast the swirl turns; below 0 turns the other way."] = "Wie schnell sich der Wirbel dreht; unter 0 dreht er andersherum."
L["The game's own screen effects closing in at the edges."] = "Die Bildschirmeffekte des Spiels selbst, die sich an den Rändern zusammenziehen."
L["A wave of the game's art creeps in on each heartbeat."] = "Mit jedem Herzschlag kriecht eine Welle der Spielgrafik herein."
L["Which of the game's effects shows."] = "Welcher Effekt des Spiels erscheint."
L["What shape cuts the effect to the screen's edges."] = "Welche Form den Effekt an den Bildschirmrändern zuschneidet."
L["Tint the effect to your theme or keep its own colors."] = "Den Effekt in deinem Thema tönen oder seine eigenen Farben behalten."
L["A second game effect over the first."] = "Ein zweiter Spieleffekt über dem ersten."
L["The game's effects slide slowly under their edge."] = "Die Effekte des Spiels gleiten langsam unter ihrem Rand."
L["One of the game's full-screen effects closing in as you weaken."] = "Einer der Vollbildeffekte des Spiels, der sich zusammenzieht, wenn du schwächer wirst."
L["Turns Vitals Vision on or off."] = "Schaltet Vitals Vision ein oder aus."
L["The screen's edges close in as your health drops."] = "Die Bildschirmränder ziehen sich zusammen, wenn deine Gesundheit sinkt."
L["How strong the edges are out of a fight."] = "Wie stark die Ränder außerhalb eines Kampfes sind."
L["Ramp up"] = "Anstieg"
L["Higher makes the edges close in slowly at first, then faster."] = "Höher lässt die Ränder sich erst langsam, dann schneller zusammenziehen."
L["Replace game's low health flash setting"] = "Blinken bei niedriger Gesundheit des Spiels ersetzen"
L["When the game's Do Not Flash Screen at Low Health setting is ticked, the edges don't show."] = "Ist die Spieleinstellung „Bildschirm bei niedriger Gesundheit nicht blinken lassen“ angehakt, erscheinen die Ränder nicht."
L["Game setting: |cffff8000no flash|r (edges off while followed)"] = "Spieleinstellung: |cffff8000kein Blinken|r (Ränder aus, solange befolgt)"
L["Game setting: |cff00ff00flash on|r"] = "Spieleinstellung: |cff00ff00Blinken an|r"
L["How fast the edges close in when your health drops."] = "Wie schnell sich die Ränder zusammenziehen, wenn deine Gesundheit sinkt."
L["How fast the edges lift when you're healed."] = "Wie schnell die Ränder weichen, wenn du geheilt wirst."
L["Smaller hits that add up to this much of your health count as a big one."] = "Kleinere Treffer, die sich auf so viel deiner Gesundheit summieren, zählen als großer."

-- Atmosphere/TeleportVision.lua
L["Teleport Vision"] = "Teleport Vision"
L["shown"] = "gezeigt"
L["A Hearthstone or teleport cast, with its scene playing"] = "Ein Ruhestein- oder Teleportzauber, während seine Szene läuft"
L["Teleport Vision colors: stopped."] = "Farben von Teleport Vision: gestoppt."
L["Teleport Vision colors: all %d shown."] = "Farben von Teleport Vision: alle %d gezeigt."
L["Teleport Vision colors: %d specs, %d seconds each (/cine teleport colors again to stop)."] = "Farben von Teleport Vision: %d Spezialisierungen, je %d Sekunden (/cine teleport colors erneut zum Stoppen)."
L["A glowing portal rim closes in around you as you cast a Hearthstone or teleport."] = "Ein leuchtender Portalrand schließt sich um dich, während du einen Ruhestein oder Teleport wirkst."
L["Shows a glowing portal around you as you cast a teleport."] = "Zeigt ein leuchtendes Portal um dich, während du einen Teleport wirkst."
L["The portal's color: your class and spec's, any class's, or your own."] = "Die Farbe des Portals: die deiner Klasse und Spezialisierung, die einer beliebigen Klasse oder deine eigene."
L["Clouds in its color swirl outside the rim, filling the screen."] = "Wolken in seiner Farbe wirbeln außerhalb des Rands und füllen den Bildschirm."
L["Black edges close in from the sides as the cast fills."] = "Schwarze Ränder ziehen sich von den Seiten zusammen, während sich der Zauber füllt."
L["How long before the cast ends the screen goes fully black; 0 turns it off."] = "Wie lange vor dem Ende des Zaubers der Bildschirm ganz schwarz wird; 0 schaltet es aus."
L["Fades out your cast bar early in the cast, so the portal shows its progress."] = "Blendet deine Zauberleiste früh im Zauber aus, damit das Portal den Fortschritt zeigt."
L["Fades out the tooltip while you cast."] = "Blendet den Tooltip aus, während du zauberst."

