L["Shown by the key group %s (Keybinds page, Frames tab): press its key again to hide it"] = "Gezeigt durch die Tastengruppe %s (Seite Tastenbelegungen, Reiter Rahmen): Drück ihre Taste erneut, um es zu verbergen"
