L["Update Layout"] = "Layout aktualisieren"
L["Rebuilds the Follow HUD layout, losing any Edit Mode changes made to it."] = "Baut das Folge-HUD-Layout neu auf; Änderungen im Bearbeitungsmodus daran gehen verloren."
L["Shows the pieces you can pick from."] = "Zeigt die Teile, aus denen du wählen kannst."
L["Your health and power"] = "Deine Gesundheit und Ressource"
L["Set Up Again"] = "Erneut einrichten"
L["Hide Pieces"] = "Teile ausblenden"
L["Change Pieces"] = "Teile ändern"
L["Not set up on this profile."] = "Auf diesem Profil nicht eingerichtet."
L["Set up, with the layout made on %s."] = "Eingerichtet, mit dem am %s erstellten Layout."
L["Set up, without a layout of its own."] = "Eingerichtet, ohne eigenes Layout."

-- Camera/CameraScriptsPage.lua
L["Until a fly-by's time on this flight"] = "Bis zur Zeit eines Vorbeiflugs auf diesem Flug"
L["Until %s to %s s go by"] = "Bis %s bis %s s vergangen sind"
L["Sway within %s° of where the sway began over %s s"] = "Innerhalb von %s° um den Pendelbeginn pendeln, über %s s"
L["Spin from %s to %s°/s, for %s s"] = "Drehen von %s bis %s°/s, für %s s"
L["Spin from %s to %s°/s, until it ends"] = "Drehen von %s bis %s°/s, bis es endet"
L["Follow your turns, catching up %s s after"] = "Deinen Drehungen folgen, %s s danach aufholen"
L["Keep up with who's talking, %s°/s at most"] = "Dem Sprecher folgen, höchstens %s°/s"
L["Swing behind you over %s s"] = "Über %s s hinter dich schwenken"
L["Undo its turns and tilts over %s s"] = "Seine Drehungen und Neigungen über %s s rückgängig machen"
L["Undo its turns, tilts and zoom over %s s"] = "Seine Drehungen, Neigungen und Zoom über %s s rückgängig machen"
L["Pop out to drag the window anywhere, or dock it beside the settings."] = "Herauslösen, um das Fenster frei zu ziehen, oder neben den Einstellungen andocken."
L["0 s"] = "0 s"
L["Speed match"] = "Tempo angleichen"
L["%s yd/s"] = "%s m/s"
L["%s°/s"] = "%s°/s"
L["%s s"] = "%s s"
L["Nearest"] = "Nächste"
L["Shortest"] = "Kürzeste"
L["Every camera as a script of small steps you can copy and change."] = "Jede Kamera als Skript aus kleinen Schritten, das du kopieren und ändern kannst."
L["Deletes this script; click twice to confirm."] = "Löscht dieses Skript; zum Bestätigen zweimal klicken."
L["Puts our script back in place of your changes; click twice to confirm."] = "Setzt unser Skript anstelle deiner Änderungen zurück; zum Bestätigen zweimal klicken."
L["Runs the camera through this script now; click again to stop."] = "Lässt die Kamera jetzt dieses Skript durchlaufen; erneut klicken zum Stoppen."
L["Untick to keep the camera running when this happens."] = "Haken entfernen, damit die Kamera weiterläuft, wenn das passiert."
L["Shows a Stop camera button on screen while this camera runs."] = "Zeigt eine Taste Kamera stoppen auf dem Bildschirm, solange diese Kamera läuft."
L["What stops the camera, plus its edge haze and Stop button."] = "Was die Kamera stoppt, dazu ihr Randdunst und die Stopptaste."
L["Turns this tab of the script on or off."] = "Schaltet diesen Reiter des Skripts ein oder aus."
L["Not a script yet: it needs %s, which the runner doesn't have yet."] = "Noch kein Skript: Es braucht %s, was der Ablauf noch nicht kann."
L["Starts when: no trigger yet."] = "Startet, wenn: noch kein Auslöser."

