L["Scene off"] = "Szene aus"
L["%d scenes off"] = "%d Szenen aus"

-- Options.lua
L["HUD"] = "HUD"
L["While you're flagged for PvP, and in battlegrounds and arenas."] = "Solange du für PvP markiert bist, sowie in Schlachtfeldern und Arenen."
L["< 100% Calm"] = "< 100% Ruhe"
L["Calm"] = "Ruhe"
L["< 100% (not full)"] = "< 100% (nicht voll)"
L["< 100% Calm (not full, only during Calm Timer)"] = "< 100% Ruhe (nicht voll, nur während des Ruhe-Timers)"
L["Puts this page's settings back to your profile's values."] = "Setzt die Einstellungen dieser Seite auf die Werte deines Profils zurück."
L["page"] = "Seite"
L["Click it for quick options and a link to these settings, drag to move it."] = "Klick darauf für Schnelloptionen und einen Link zu diesen Einstellungen, ziehen zum Verschieben."
L["Show in addon compartment"] = "Im Addonfach zeigen"
L["Lists Cinematic in the game's addon list by the minimap."] = "Listet Cinematic in der Addon-Liste des Spiels an der Minikarte."
L["The minimap button glows while a vision is doing something."] = "Die Minikarten-Taste leuchtet, solange eine Vision etwas tut."
L["Suggest /cine commands while typing"] = "/cine-Befehle beim Tippen vorschlagen"
L["Typing /cine in chat lists the commands that fit."] = "Tippst du /cine im Chat, werden die passenden Befehle aufgelistet."
L["The language Cinematic's text is in; a change needs a reload."] = "Die Sprache der Texte von Cinematic; eine Änderung braucht ein Neuladen."
L["The look of Cinematic's settings windows: HD is flat and dark, and SD looks like the game's own."] = "Das Aussehen der Einstellungsfenster von Cinematic: HD ist flach und dunkel, SD sieht aus wie die des Spiels."
L["The game's %s is off"] = "%s des Spiels ist aus"
L["Couldn't turn it on right now; try again after the fight."] = "Konnte es gerade nicht einschalten; versuch es nach dem Kampf noch einmal."
L["On. Right-click to turn all its tabs off."] = "An. Rechtsklick schaltet alle seine Reiter aus."
L["Off. Right-click to turn all its tabs on."] = "Aus. Rechtsklick schaltet alle seine Reiter ein."
L["Cinematic is about bringing Azeroth to life: your screen changes with the moment you're in, hiding what you don't need and showing what you do."] = "Bei Cinematic geht es darum, Azeroth zum Leben zu erwecken: Dein Bildschirm ändert sich mit dem Moment, in dem du bist, verbirgt, was du nicht brauchst, und zeigt, was du brauchst."
L["Reset Settings keeps what you made, Reset EVERYTHING deletes it all, and both reload the UI."] = "Einstellungen zurücksetzen behält, was du erstellt hast, ALLES zurücksetzen löscht alles, und beide laden das UI neu."
L["Effects that play over the world when something happens."] = "Effekte, die über der Welt spielen, wenn etwas passiert."
L["How the whole interface looks."] = "Wie die ganze Oberfläche aussieht."
L["Atmosphere"] = "Atmosphäre"
L["The camera coming alive."] = "Die Kamera wird lebendig."
L["How fast the UI fades, the Calm Timer, and what takes you out of CineMode."] = "Wie schnell das UI ausblendet, der Ruhe-Timer und was dich aus CineMode holt."
L["Your interface fades away but comes back when you need it to."] = "Deine Oberfläche blendet aus, kommt aber zurück, wenn du sie brauchst."
L["Nothing fades right now."] = "Gerade blendet nichts aus."
L["Click to turn CineMode off."] = "Klicke, um CineMode auszuschalten."
L["Click to turn CineMode on."] = "Klicke, um CineMode einzuschalten."
L["Click to see why."] = "Klicke, um zu sehen, warum."
L["CineMode is on"] = "CineMode ist an"
L["CineMode is off"] = "CineMode ist aus"
L["Cameras (Camera tab) is set to CineMode."] = "Kameras (Reiter Kamera) ist auf CineMode gestellt."
L["This page does nothing."] = "Diese Seite tut nichts."
L["Works while CineMode is on, and outside it while friendly nameplates show."] = "Wirkt, solange CineMode an ist, und außerhalb davon, solange freundliche Namensplaketten gezeigt werden."
L["Works only while CineMode is on."] = "Wirkt nur, solange CineMode an ist."
L["Works while CineMode is off too."] = "Wirkt auch, solange CineMode aus ist."
L["This page works as its settings say."] = "Diese Seite wirkt, wie ihre Einstellungen sagen."
L["Click to turn it on or off."] = "Klicke, um es ein- oder auszuschalten."
L["off with %s"] = "aus mit %s"
L["How fast the UI fades and what brings it back while CineMode is on."] = "Wie schnell das UI ausblendet und was es zurückholt, solange CineMode an ist."
L["How fast the UI fades, the Calm Timer, and fights coming in."] = "Wie schnell das UI ausblendet, der Ruhe-Timer und beginnende Kämpfe."
L["What takes you out of CineMode: fights, places, groups, moving and windows."] = "Was dich aus CineMode holt: Kämpfe, Orte, Gruppen, Bewegung und Fenster."
L["The minimap button, /cine hints, language and the menus' look."] = "Die Minikarten-Taste, /cine-Hinweise, Sprache und das Aussehen der Menüs."
L["How long things take to fade in out of combat."] = "Wie lange Dinge außerhalb des Kampfes zum Einblenden brauchen."
L["How long things take to fade out."] = "Wie lange Dinge zum Ausblenden brauchen."
L["How long things take to fade in during a fight."] = "Wie lange Dinge im Kampf zum Einblenden brauchen."
L["Casts count too when a rule uses Casting."] = "Zauber zählen auch, wenn eine Regel Zaubern nutzt."
L["As soon as a fight ends"] = "Sobald ein Kampf endet"
L["How long after a fight before CineMode comes back."] = "Wie lange nach einem Kampf, bis CineMode zurückkommt."
L["Ends the Calm Timer early once your health and power are back to full."] = "Beendet den Ruhe-Timer früher, sobald deine Gesundheit und Ressource wieder voll sind."
L["With a pet out, its health must be full too."] = "Ist ein Begleiter draußen, muss auch seine Gesundheit voll sein."
L["Exit CineMode while an NPC window, like a quest giver or vendor, is open."] = "CineMode verlassen, solange ein NPC-Fenster wie ein Questgeber oder Händler offen ist."
L["Exit CineMode while a game window, like your bags or the map, is open."] = "CineMode verlassen, solange ein Spielfenster wie deine Taschen oder die Karte offen ist."
L["Picking up an item or spell brings the UI back until you put it down."] = "Einen Gegenstand oder Zauber aufzunehmen holt das UI zurück, bis du ihn ablegst."
L["How long things must stay calm before CineMode comes back."] = "Wie lange es ruhig bleiben muss, bevor CineMode zurückkommt."
L["Casting at an enemy out of combat brings up your combat frames."] = "Ein Zauber auf einen Gegner außerhalb des Kampfes holt deine Kampfrahmen hervor."
L["Being in combat brings the UI back."] = "Im Kampf kommt das UI zurück."
L["In the open world"] = "In der offenen Welt"
L["Anywhere outside cities, dungeons and raids."] = "Überall außerhalb von Städten, Dungeons und Schlachtzügen."
L["Capital cities, including Dalaran."] = "Hauptstädte, Dalaran eingeschlossen."
L["While you're flagged for PvP out in the world."] = "Solange du draußen in der Welt für PvP markiert bist."
L["In battlegrounds"] = "In Schlachtfeldern"
L["Battlegrounds and arenas."] = "Schlachtfelder und Arenen."
L["Back after stopping"] = "Zurück nach Anhalten"
L["CineMode comes back once you've stood still this long."] = "CineMode kommt zurück, wenn du so lange stillgestanden hast."
L["Back after moving"] = "Zurück nach Bewegung"
L["CineMode comes back once you've kept moving this long."] = "CineMode kommt zurück, wenn du dich so lange weiterbewegt hast."
L["Allow outside CineMode"] = "Außerhalb von CineMode erlauben"
L["CineMode hides your buffs and debuffs: pick what brings them back."] = "CineMode verbirgt deine Stärkungs- und Schwächungszauber: Wähl, was sie zurückholt."
L["Gaining or refreshing a buff briefly shows your buffs and debuffs."] = "Einen Stärkungszauber zu erhalten oder zu erneuern zeigt kurz deine Stärkungs- und Schwächungszauber."
L["Lets this page bring your hidden buffs and debuffs back in CineMode."] = "Lässt diese Seite deine verborgenen Stärkungs- und Schwächungszauber in CineMode zurückholen."
L["What brings your hidden buffs and debuffs up for a while."] = "Was deine verborgenen Stärkungs- und Schwächungszauber eine Weile hervorholt."
L["Buffs you or your pet cast on yourself don't bring them up."] = "Stärkungszauber, die du oder dein Begleiter auf dich wirken, holen sie nicht hervor."
L["Not while skyriding"] = "Nicht beim Himmelsreiten"
L["No buff brings them up while you're on a skyriding mount."] = "Kein Stärkungszauber holt sie hervor, solange du auf einem Himmelsreittier bist."
L["Only the buff you gained or refreshed shows."] = "Nur der erhaltene oder erneuerte Stärkungszauber erscheint."
L["Keep ones lasting less than up until they run out"] = "Kürzere als diese bis zum Ablauf zeigen"
L["A short buff stays up for as long as it lasts."] = "Ein kurzer Stärkungszauber bleibt sichtbar, solange er wirkt."
L["Gaining or refreshing a debuff briefly shows your debuffs."] = "Einen Schwächungszauber zu erhalten oder zu erneuern zeigt kurz deine Schwächungszauber."
L["Only within the Calm Timer after a fight."] = "Nur im Ruhe-Timer nach einem Kampf."
L["Keeps them up while you have any debuff."] = "Hält sie sichtbar, solange du irgendeinen Schwächungszauber hast."
L["Debuffs that last longer than this don't bring them up."] = "Schwächungszauber, die länger dauern, holen sie nicht hervor."
L["Override Default Buff Reveal Time"] = "Standard-Einblendzeit für Stärkungszauber ändern"
L["How long a new buff keeps the buffs up."] = "Wie lange ein neuer Stärkungszauber die Stärkungszauber sichtbar hält."
L["Override Default Debuff Reveal Time"] = "Standard-Einblendzeit für Schwächungszauber ändern"
L["How long a new debuff keeps the buffs up."] = "Wie lange ein neuer Schwächungszauber die Zauber sichtbar hält."
L["Gaining this doesn't bring your buffs up; type a spell ID or name."] = "Das zu erhalten holt deine Stärkungszauber nicht hervor; gib eine Zauber-ID oder einen Namen ein."
L["Keeps drifting to new random distances after the first pull-back."] = "Treibt nach dem ersten Zurückziehen weiter zu neuen zufälligen Abständen."
L["How much closer than your own zoom the random zoom may come."] = "Wie viel näher als dein eigener Zoom der Zufallszoom kommen darf."
L["How much of each zoom is spent speeding up and slowing down."] = "Wie viel jedes Zooms auf Beschleunigen und Abbremsen entfällt."
L["Each pause varies at random by up to this much."] = "Jede Pause schwankt zufällig um bis zu so viel."
L["Raises the game's max camera distance while pulled back."] = "Erhöht beim Zurückziehen den maximalen Kameraabstand des Spiels."
L["Lets the cameras start as the rows below say."] = "Lässt die Kameras starten, wie die Zeilen unten sagen."
L["Top speed in the middle of a sweep."] = "Höchsttempo in der Mitte eines Schwenks."
L["Each new angle is at least this many degrees from the last."] = "Jeder neue Winkel liegt mindestens so viele Grad vom letzten entfernt."
L["How far the camera may sway to either side."] = "Wie weit die Kamera zu jeder Seite pendeln darf."
L["Each move also tilts the camera to a random angle between these limits."] = "Jede Bewegung neigt die Kamera auch auf einen zufälligen Winkel zwischen diesen Grenzen."
L["The camera never tilts more than this far below where it started."] = "Die Kamera neigt sich nie weiter als so weit unter ihren Ausgangspunkt."
L["How much of each move is spent speeding up and slowing down."] = "Wie viel jeder Bewegung auf Beschleunigen und Abbremsen entfällt."
L["How long the camera rests between sweeps."] = "Wie lange die Kamera zwischen Schwenks ruht."
L["Puts this camera's settings back to your profile's values."] = "Setzt die Einstellungen dieser Kamera auf die Werte deines Profils zurück."
L["Runs this camera for 30 seconds where you stand."] = "Lässt diese Kamera 30 Sekunden dort laufen, wo du stehst."
L["The camera slowly pulls back, then drifts in and out."] = "Die Kamera zieht sich langsam zurück und treibt dann vor und zurück."
L["After you move the camera yourself, it waits this long before carrying on."] = "Bewegst du die Kamera selbst, wartet sie so lange, bevor sie weitermacht."
L["Doing the emote or pressing the sit key."] = "Das Emote ausführen oder die Sitzen-Taste drücken."
L["Clicking Sit, Kneel or Lie down on the campfire card, or its fire button (Emote Vision)."] = "Auf der Lagerfeuer-Karte Sitzen, Knien oder Hinlegen anklicken, oder ihre Feuertaste (Emote Vision)."
L["Doing the emote, until you move or jump."] = "Das Emote ausführen, bis du dich bewegst oder springst."
L["Right-clicking a seat to sit on it."] = "Einen Sitzplatz rechtsklicken, um dich daraufzusetzen."
L["Unsheathing your weapon with your Sheathe key out of combat."] = "Außerhalb des Kampfes die Waffe mit deiner Taste zum Ziehen ziehen."
L["Casting your Hearthstone."] = "Deinen Ruhestein wirken."
L["Casting a teleport spell."] = "Einen Teleportzauber wirken."
L["Logging out where the game counts down first."] = "Ausloggen, wo das Spiel erst herunterzählt."
L["Doing the emote while standing still."] = "Das Emote im Stillstehen ausführen."
L["Casting Fishing, until you move or jump."] = "Angeln wirken, bis du dich bewegst oder springst."
L["Being flagged AFK."] = "Als AFK markiert sein."
L["Standing still for the time below with nothing else going on."] = "Für die Zeit unten stillstehen, ohne dass sonst etwas passiert."
L["Taking off on a flight path."] = "Auf einer Flugroute abheben."
L["Talking to a quest giver."] = "Mit einem Questgeber sprechen."
L["Talking to an NPC about a quest step."] = "Mit einem NPC über einen Questschritt sprechen."
L["On flight paths, the camera sways side to side with an occasional fly-by."] = "Auf Flugrouten pendelt die Kamera hin und her, mit gelegentlichem Vorbeiflug."
L["Your target's frames fade until you pick a new target or land."] = "Die Rahmen deines Ziels blenden aus, bis du ein neues Ziel wählst oder landest."
L["Sway from side to side"] = "Hin und her pendeln"
L["The camera sways from side to side around where it started."] = "Die Kamera pendelt um ihren Ausgangspunkt hin und her."
L["Your character does /look as a fly-by starts, which players nearby see."] = "Deine Figur macht /look, wenn ein Vorbeiflug beginnt, was Spieler in der Nähe sehen."
L["About one fly-by per this many seconds of flight."] = "Etwa ein Vorbeiflug pro so vielen Sekunden Flug."
L["Turn round"] = "Umdrehen"
L["Turn back before landing"] = "Vor der Landung zurückdrehen"
L["Before you land, the camera turns back to where it was at takeoff."] = "Vor der Landung dreht sich die Kamera zurück, wo sie beim Abheben war."
L["Turned back by"] = "Zurückgedreht bis"
L["How long before landing the camera has settled."] = "Wie lange vor der Landung die Kamera zur Ruhe gekommen ist."
L["When you stand still a while or go AFK, the camera slowly circles your character."] = "Stehst du eine Weile still oder gehst AFK, umkreist die Kamera langsam deine Figur."
L["The camera sweeps around your character, pausing between sweeps."] = "Die Kamera schwenkt um deine Figur und pausiert zwischen den Schwenks."
L["While you auto-run, the camera follows along until you stop or steer."] = "Beim Autolauf folgt die Kamera mit, bis du anhältst oder lenkst."
L["The camera eases out a little, then drifts in and out."] = "Die Kamera geht sanft etwas heraus und treibt dann vor und zurück."
L["When you rest, sit or dance, the camera slowly turns to face you and eases in."] = "Rastest, sitzt oder tanzt du, dreht sich die Kamera langsam zu dir und kommt sanft heran."
L["How far the camera comes down toward the ground as it turns."] = "Wie weit die Kamera beim Drehen zum Boden herunterkommt."
L["The camera eases in close, then drifts a little in and out."] = "Die Kamera kommt sanft nah heran und treibt dann etwas vor und zurück."
L["The close-up distance the cozy camera zooms in to."] = "Der Nahabstand, auf den die gemütliche Kamera heranzoomt."
L["How much lower the camera sways, to look out across the view."] = "Wie viel tiefer die Kamera pendelt, um über die Aussicht zu blicken."
L["The camera eases out a little, then drifts slowly in and out."] = "Die Kamera geht sanft etwas heraus und treibt dann langsam vor und zurück."
L["The camera sways a little from side to side."] = "Die Kamera pendelt ein wenig hin und her."
L["How much lower the camera sways, to look out across the water."] = "Wie viel tiefer die Kamera pendelt, um über das Wasser zu blicken."
L["When you die, the camera slowly circles your body until you release or are revived."] = "Stirbst du, umkreist die Kamera langsam deinen Körper, bis du freilässt oder wiederbelebt wirst."
L["If you die in a boss fight, the death camera waits for it to end."] = "Stirbst du in einem Bosskampf, wartet die Todeskamera auf sein Ende."
L["No death camera when you can come back yourself, like with a soulstone."] = "Keine Todeskamera, wenn du selbst zurückkommen kannst, etwa mit einem Seelenstein."
L["Adds a button under the release popup to get your own view back."] = "Fügt unter dem Freilassen-Fenster eine Taste hinzu, um deine eigene Sicht zurückzubekommen."
L["How far the camera pulls back while you're dead."] = "Wie weit die Kamera zurückgeht, solange du tot bist."
L["How far the camera rises to look down on your body."] = "Wie weit die Kamera steigt, um auf deinen Körper hinabzuschauen."
L["The groups ticked here stay up while the death camera hides your frames."] = "Die hier angehakten Gruppen bleiben sichtbar, während die Todeskamera deine Rahmen verbirgt."
L["Music file IDs, separated by commas; one plays at random when you die."] = "Musikdatei-IDs, durch Kommas getrennt; eine davon spielt zufällig, wenn du stirbst."
L["The camera turns toward NPCs as they talk near you."] = "Die Kamera dreht sich zu NPCs, wenn sie in deiner Nähe sprechen."
L["The fastest the camera swings toward a new speaker."] = "Wie schnell die Kamera höchstens zu einem neuen Sprecher schwenkt."
L["How far from the screen's center the speaker ends up."] = "Wie weit von der Bildschirmmitte der Sprecher landet."
L["How far the camera drifts side to side once settled."] = "Wie weit die Kamera hin und her treibt, sobald sie zur Ruhe gekommen ist."
L["The camera turns around to find speakers you can't see."] = "Die Kamera dreht sich um, um Sprecher zu finden, die du nicht siehst."
L["Snaps to speakers, adds a tall letterbox with subtitles and fades the whole UI."] = "Springt zu Sprechern, fügt hohe Kinobalken mit Untertiteln hinzu und blendet das ganze UI aus."
L["How fast the camera zooms back out once the talking is over."] = "Wie schnell die Kamera wieder herauszoomt, sobald das Gespräch vorbei ist."
L["The longest a zoom in or out can take."] = "Wie lange ein Zoom hinein oder heraus höchstens dauern kann."
L["How long no one must talk before the camera turns back."] = "Wie lange niemand sprechen darf, bevor die Kamera zurückdreht."
L["When you talk to a quest giver, the camera zooms in and looks past you at them."] = "Sprichst du mit einem Questgeber, zoomt die Kamera heran und schaut an dir vorbei auf ihn."
L["Also zooms in for NPCs with nothing to say about quests."] = "Zoomt auch bei NPCs heran, die nichts über Quests zu sagen haben."
L["The camera stays put when a quest giver only has dailies or weeklies."] = "Die Kamera bleibt, wo sie ist, wenn ein Questgeber nur tägliche oder wöchentliche Quests hat."
L["How far the camera turns to one side to look past you."] = "Wie weit sich die Kamera zur Seite dreht, um an dir vorbeizuschauen."
L["How long the turn to the side takes."] = "Wie lange die Drehung zur Seite dauert."
L["How fast the camera zooms back out once you walk away."] = "Wie schnell die Kamera wieder herauszoomt, sobald du weggehst."
L["How far the camera comes down toward eye level."] = "Wie weit die Kamera zur Augenhöhe herunterkommt."
L["When you cast your Hearthstone or a teleport, the camera spins around you as it zooms in."] = "Wirkst du deinen Ruhestein oder einen Teleport, dreht sich die Kamera um dich, während sie heranzoomt."
L["The distance the zoom ends at as the cast finishes."] = "Der Abstand, bei dem der Zoom endet, wenn der Zauber fertig ist."
L["Canceling"] = "Abbrechen"
L["If you cancel the cast, the camera turns back to where it was."] = "Brichst du den Zauber ab, dreht sich die Kamera zurück, wo sie war."
L["Extra settings for cameras that aren't on the Scripts page yet."] = "Zusätzliche Einstellungen für Kameras, die noch nicht auf der Seite Skripte sind."
L["Mouse Turn"] = "Mausdrehung"
L["Keeps right-mouse turning smooth by capping and easing its speed."] = "Hält das Drehen mit der rechten Maustaste weich, indem es das Tempo begrenzt und abfedert."
L["Cap"] = "Begrenzen"
L["Cap right-click turn speed"] = "Drehtempo mit Rechtsklick begrenzen"
L["Right-click turning never goes faster than the speed below."] = "Drehen mit Rechtsklick wird nie schneller als das Tempo unten."
L["Top turn speed"] = "Höchstes Drehtempo"
L["The fastest you can turn."] = "Wie schnell du dich höchstens drehen kannst."
L["Ease back over"] = "Sanft zurück über"
L["How long your own Mouse Look Speed takes to come back after you slow down."] = "Wie lange deine eigene Mausumsehgeschwindigkeit nach dem Abbremsen braucht, um zurückzukommen."
L["Ramp up right-click turn speed"] = "Drehtempo mit Rechtsklick ansteigen lassen"
L["Each right-click turn starts slow and builds up to your own speed."] = "Jede Drehung mit Rechtsklick beginnt langsam und steigert sich auf dein eigenes Tempo."
L["Start at"] = "Beginnen bei"
L["%d%% of your speed"] = "%d%% deines Tempos"
L["How fast a turn starts, as a share of your own Mouse Look Speed."] = "Wie schnell eine Drehung beginnt, als Anteil deiner eigenen Mausumsehgeschwindigkeit."
L["Up to full speed over"] = "Auf volles Tempo über"
L["How long a turn takes to build up to full speed."] = "Wie lange eine Drehung braucht, um volles Tempo zu erreichen."
L["Slow looking up and down too"] = "Auch Hoch- und Runterschauen verlangsamen"
L["Looking up and down slows by the same share as turning."] = "Hoch- und Runterschauen wird um denselben Anteil langsamer wie das Drehen."
L["Turns the whole Atmosphere hub on or off at once."] = "Schaltet die ganze Atmosphäre-Übersicht auf einmal ein oder aus."
L["How the game world looks in CineMode: vignette, inn glow, weather and depth of field."] = "Wie die Spielwelt in CineMode aussieht: Vignette, Gasthausschein, Wetter und Tiefenschärfe."
L["Pick where and when each effect shows in CineMode."] = "Wähl, wo und wann jeder Effekt in CineMode erscheint."
L["Shows all the time in CineMode, fights included."] = "Erscheint die ganze Zeit in CineMode, Kämpfe eingeschlossen."
L["Rain, snow and sandstorms tint the scene, more strongly in heavier weather."] = "Regen, Schnee und Sandstürme tönen die Szene, stärker bei heftigerem Wetter."
L["Reduce view distance in bad weather"] = "Sichtweite bei schlechtem Wetter verringern"
L["Brings the view distance in during rain, snow or sandstorms, more the heavier it gets."] = "Verringert die Sichtweite bei Regen, Schnee oder Sandstürmen, umso mehr, je heftiger es wird."
L["The game's graphics settings one by one, shared by every profile on this computer."] = "Die Grafikeinstellungen des Spiels einzeln, gemeinsam für jedes Profil auf diesem Computer."
L["Uses the settings below, or the game's own when turned off."] = "Nutzt die Einstellungen unten, oder ausgeschaltet die des Spiels."
L["World"] = "Welt"
L["Ground clutter, view distance, detail and shadows."] = "Bodenbewuchs, Sichtweite, Details und Schatten."
L["Sky and water"] = "Himmel und Wasser"
L["Clouds, fog, reflections and ripples."] = "Wolken, Nebel, Spiegelungen und Wellen."
L["Effects"] = "Effekte"
L["Particles, glow, blood and sharpening."] = "Partikel, Leuchten, Blut und Schärfung."
L["HDR"] = "HDR"
L["HDR output and brightness."] = "HDR-Ausgabe und Helligkeit."
L["Nameplate distance and zoom distance."] = "Namensplakettenabstand und Zoomabstand."
L["How far away grass and flowers start thinning out."] = "Ab welcher Entfernung Gras und Blumen ausdünnen."
L["How far the land is drawn in full; very demanding on frame rate."] = "Wie weit das Land voll gezeichnet wird; sehr anspruchsvoll für die Bildrate."
L["How far away trees, rocks and other objects keep their full detail."] = "Bis zu welcher Entfernung Bäume, Felsen und andere Objekte volle Details behalten."
L["How far away small objects stay before they fade out."] = "Bis zu welcher Entfernung kleine Objekte bleiben, bevor sie ausblenden."
L["How far away creatures and characters keep their full detail."] = "Bis zu welcher Entfernung Kreaturen und Charaktere volle Details behalten."
L["How far away nameplates show, in yards."] = "Bis zu welcher Entfernung Namensplaketten erscheinen, in Metern."
L["How far out you can zoom the camera."] = "Wie weit du die Kamera herauszoomen kannst."
L["Higher gives sharper shadow edges, lower saves frame rate."] = "Höher gibt schärfere Schattenkanten, niedriger spart Bildrate."
L["Horizon distance"] = "Horizontweite"
L["How far the flat horizon past the land reaches."] = "Wie weit der flache Horizont hinter dem Land reicht."
L["Sky detail"] = "Himmelsdetails"
L["How detailed the clouds and sky are."] = "Wie detailliert Wolken und Himmel sind."
L["Volumetric fog"] = "Volumetrischer Nebel"
L["Fog with depth in place of the usual distance fog."] = "Nebel mit Tiefe statt des üblichen Entfernungsnebels."
L["Water reflections"] = "Wasserspiegelungen"
L["How much of the world water reflects."] = "Wie viel der Welt sich im Wasser spiegelt."
L["Water ripples"] = "Wasserwellen"
L["How detailed the ripples on water are."] = "Wie detailliert die Wellen auf dem Wasser sind."
L["Particle density"] = "Partikeldichte"
L["How many particles spells and effects show."] = "Wie viele Partikel Zauber und Effekte zeigen."
L["Full-screen glow"] = "Vollbild-Leuchten"
L["A soft glow around bright light."] = "Ein weiches Leuchten um helles Licht."
L["Gray screen on death"] = "Grauer Bildschirm beim Tod"
L["The world turns gray while you're dead."] = "Die Welt wird grau, solange du tot bist."
L["Blood and gore"] = "Blut und Gewalt"
L["How much blood shows in fights, from none to the most."] = "Wie viel Blut in Kämpfen zu sehen ist, von keinem bis zum meisten."
L["Always sharpen"] = "Immer schärfen"
L["Sharpens the picture even at full render scale."] = "Schärft das Bild auch bei voller Renderskalierung."
L["HDR output"] = "HDR-Ausgabe"
L["Sends HDR to your monitor; Windows HDR must be on and Auto HDR off."] = "Sendet HDR an deinen Monitor; Windows-HDR muss an und Auto-HDR aus sein."
L["Use peak brightness"] = "Spitzenhelligkeit nutzen"
L["Peak brightness"] = "Spitzenhelligkeit"
L["Your monitor's peak brightness, in nits."] = "Die Spitzenhelligkeit deines Monitors, in Nits."
L["HDR strength"] = "HDR-Stärke"
L["How strong HDR is; works with peak brightness only."] = "Wie stark HDR ist; wirkt nur mit Spitzenhelligkeit."
L["Use reference brightness"] = "Referenzhelligkeit nutzen"
L["Reference brightness"] = "Referenzhelligkeit"
L["How bright white looks in HDR, in nits."] = "Wie hell Weiß in HDR aussieht, in Nits."
L["Sky and weather"] = "Himmel und Wetter"
L["Water"] = "Wasser"
L["Restart graphics"] = "Grafik neu starten"
L["Restarts the game's graphics without leaving the game; the screen goes black for a moment."] = "Startet die Grafik des Spiels neu, ohne das Spiel zu verlassen; der Bildschirm wird kurz schwarz."
L["Sound and music during CineMode; your own sound settings come back afterward."] = "Ton und Musik während CineMode; deine eigenen Toneinstellungen kommen danach zurück."
L["Plays music when a camera starts in CineMode and fades it out when the UI returns."] = "Spielt Musik, wenn eine Kamera in CineMode startet, und blendet sie aus, wenn das UI zurückkommt."
L["Pick where and when music can play in CineMode."] = "Wähl, wo und wann in CineMode Musik spielen darf."
L["After a camera starts music, no camera starts it again for this long."] = "Nachdem eine Kamera Musik gestartet hat, startet sie so lange keine Kamera erneut."
L["Fades music out once you leave the camera modes and move on."] = "Blendet die Musik aus, sobald du die Kameramodi verlässt und weitergehst."
L["Each row is a scene that plays its camera when one of its triggers happens."] = "Jede Zeile ist eine Szene, die ihre Kamera abspielt, wenn einer ihrer Auslöser eintritt."
L["Lets the scenes below play their cameras when their triggers happen."] = "Lässt die Szenen unten ihre Kameras abspielen, wenn ihre Auslöser eintreten."
L["Auto-running in walk mode."] = "Autolauf im Gehmodus."
L["Auto-running."] = "Autolauf."
L["Dying, until you release or are resurrected."] = "Sterben, bis du freilässt oder wiederbelebt wirst."
L["An NPC talking to you or your party; the camera swings toward whoever's talking."] = "Ein NPC spricht mit dir oder deiner Gruppe; die Kamera schwenkt zu dem, der spricht."
L["Other NPCs talking near you, once you've stood still a while."] = "Andere NPCs sprechen in deiner Nähe, sobald du eine Weile stillgestanden hast."
L["Starts music as this camera starts; needs the Audio page on."] = "Startet Musik, wenn diese Kamera startet; braucht die Seite Audio an."
L["Plays a song of its own while the death camera runs."] = "Spielt ein eigenes Lied, solange die Todeskamera läuft."
L["Brings CineMode on while this camera runs, when Start in CineMode is off."] = "Schaltet CineMode ein, solange diese Kamera läuft, wenn In CineMode starten aus ist."
L["Buff names or spell IDs, separated by commas."] = "Namen von Stärkungszaubern oder Zauber-IDs, durch Kommas getrennt."
L["Words in an object's name that mark it as a seat, separated by commas."] = "Wörter im Namen eines Objekts, die es als Sitzplatz kennzeichnen, durch Kommas getrennt."
L["How long you stand still before this row's camera starts."] = "Wie lange du stillstehst, bevor die Kamera dieser Zeile startet."
L["How long the camera waits on a quest window before it starts."] = "Wie lange die Kamera bei einem Questfenster wartet, bevor sie startet."
L["How long the camera waits on the window before it starts."] = "Wie lange die Kamera beim Fenster wartet, bevor sie startet."
L["How long you stand still before NPCs chatting nearby start this camera."] = "Wie lange du stillstehst, bevor plaudernde NPCs in der Nähe diese Kamera starten."
L["How long you keep going before this row's camera starts."] = "Wie lange du weitermachst, bevor die Kamera dieser Zeile startet."
L["Whether this row's camera may start in or after a fight."] = "Ob die Kamera dieser Zeile im oder nach einem Kampf starten darf."
L["Where this row's camera may start."] = "Wo die Kamera dieser Zeile starten darf."
L["Pause cameras while a window is open"] = "Kameras pausieren, solange ein Fenster offen ist"
L["Scenes pause while a window like the map or spellbook is open."] = "Szenen pausieren, solange ein Fenster wie die Karte oder das Zauberbuch offen ist."
L["Lists the rows by camera name or by scene name."] = "Listet die Zeilen nach Kameraname oder nach Szenenname."
L["Make a scene of your own with its triggers, camera and end."] = "Mach eine eigene Szene mit ihren Auslösern, ihrer Kamera und ihrem Ende."
L["A scene of your own; open it to set its triggers and when it ends."] = "Eine eigene Szene; öffne sie, um ihre Auslöser festzulegen und wann sie endet."
L["Copies this row just below, so you can give it another camera."] = "Kopiert diese Zeile direkt darunter, damit du ihr eine andere Kamera geben kannst."
L["Deletes this scene so it starts no camera."] = "Löscht diese Szene, sodass sie keine Kamera startet."
L["Your own name for this row, shown on the grid."] = "Dein eigener Name für diese Zeile, im Raster gezeigt."
L["The camera this row starts."] = "Die Kamera, die diese Zeile startet."
L["This row's camera may start anywhere."] = "Die Kamera dieser Zeile darf überall starten."
L["Indoors, the camera modes zoom out and swing less so they don't hit walls."] = "Drinnen zoomen und schwenken die Kameramodi weniger, damit sie nicht gegen Wände stoßen."
L["How far past your own distance the slow zoom may pull back indoors."] = "Wie weit über deinen eigenen Abstand hinaus der langsame Zoom drinnen zurückgehen darf."
L["Stops the AFK camera sweeping around you indoors, where it can hit walls."] = "Verhindert, dass die AFK-Kamera drinnen um dich schwenkt, wo sie gegen Wände stoßen kann."
L["Shows it whenever its frame shows, hovered or not."] = "Zeigt es immer, wenn sein Rahmen zeigt, mit oder ohne Maus darüber."
L["Shows it the whole time, CineMode or not."] = "Zeigt es die ganze Zeit, mit CineMode oder ohne."
L["CineMode hides everything: pick which frames show, and when."] = "CineMode verbirgt alles: Wähl, welche Rahmen erscheinen, und wann."
L["CineMode hides everything: tick which frames show, and when."] = "CineMode verbirgt alles: Hake an, welche Rahmen erscheinen, und wann."
L["CineMode hides these frames, and shows them only when their rows say."] = "CineMode verbirgt diese Rahmen und zeigt sie nur, wenn ihre Zeilen es sagen."
L["CineMode hides the frames in this section, and shows them only when their rows say."] = "CineMode verbirgt die Rahmen in diesem Abschnitt und zeigt sie nur, wenn ihre Zeilen es sagen."
L["Not in use"] = "Nicht in Gebrauch"
L["Shows or hides its parts."] = "Zeigt oder verbirgt seine Teile."
L["Shows the same parts as the Target rows."] = "Zeigt dieselben Teile wie die Zeilen von Ziel."
L["Raid-style party frames follow the Raid tab's rows."] = "Gruppenrahmen im Schlachtzugsstil folgen den Zeilen des Reiters Schlachtzug."
L["Same as"] = "Wie"
L["raid frames"] = "Schlachtzugsrahmen"
L["Opens the Raid tab."] = "Öffnet den Reiter Schlachtzug."
L["Your Edit Mode layout has Use Raid-Style Party Frames ticked."] = "In deinem Layout im Bearbeitungsmodus ist Gruppenrahmen im Schlachtzugsstil verwenden angehakt."
L["Your Edit Mode layout has Use Raid-Style Party Frames unticked."] = "In deinem Layout im Bearbeitungsmodus ist Gruppenrahmen im Schlachtzugsstil verwenden nicht angehakt."
L["Hide keybinds"] = "Tastenbelegungen ausblenden"
L["Hides the key names on the action bar buttons (1, a-Q, s-2...), CineMode or not."] = "Blendet die Tastennamen auf den Aktionstasten aus (1, a-Q, s-2 …), mit CineMode oder ohne."
L["Hide macro names"] = "Makronamen ausblenden"
L["Hides the macro names on the action bar buttons, CineMode or not."] = "Blendet die Makronamen auf den Aktionstasten aus, mit CineMode oder ohne."
L["Show while the spellbook is open"] = "Zeigen, solange das Zauberbuch offen ist"
L["Keeps your action bars up while the spellbook or macros window is open."] = "Hält deine Aktionsleisten sichtbar, solange das Zauberbuch oder Makrofenster offen ist."
L["PRD"] = "PRD"
L["Timers"] = "Timer"
L["Highlight"] = "Hervorhebung"
L["CineMode hides the unit frames: pick which show, and when."] = "CineMode verbirgt die Einheitenrahmen: Wähl, welche erscheinen, und wann."
L["CineMode hides your personal resource display: pick which parts show, and when."] = "CineMode verbirgt deine persönliche Ressourcenanzeige: Wähl, welche Teile erscheinen, und wann."
L["CineMode hides your cast bar: pick when it shows."] = "CineMode verbirgt deine Zauberleiste: Wähl, wann sie erscheint."
L["CineMode hides the action bars: pick which show, and when."] = "CineMode verbirgt die Aktionsleisten: Wähl, welche erscheinen, und wann."
L["CineMode hides your buffs and debuffs: pick when they show."] = "CineMode verbirgt deine Stärkungs- und Schwächungszauber: Wähl, wann sie erscheinen."
L["CineMode hides timers and meters: pick which show, and when."] = "CineMode verbirgt Timer und Anzeigen: Wähl, welche erscheinen, und wann."
L["CineMode hides the Cooldown Manager: pick which bars show, and when."] = "CineMode verbirgt den Abklingzeitenmanager: Wähl, welche Leisten erscheinen, und wann."
L["CineMode hides your swing timer: pick when it shows."] = "CineMode verbirgt deinen Schwungtimer: Wähl, wann er erscheint."
L["CineMode hides the chat window: pick when it shows."] = "CineMode verbirgt das Chatfenster: Wähl, wann es erscheint."
L["CineMode hides info frames and menus: pick which show, and when."] = "CineMode verbirgt Inforahmen und Menüs: Wähl, welche erscheinen, und wann."
L["CineMode hides the minimap: pick which parts show, and when."] = "CineMode verbirgt die Minikarte: Wähl, welche Teile erscheinen, und wann."
L["CineMode hides the quest tracker: pick when it shows."] = "CineMode verbirgt die Questverfolgung: Wähl, wann sie erscheint."
L["CineMode hides the party frames: pick when they show."] = "CineMode verbirgt die Gruppenrahmen: Wähl, wann sie erscheinen."
L["CineMode hides the raid frames: pick when they show."] = "CineMode verbirgt die Schlachtzugsrahmen: Wähl, wann sie erscheinen."
L["CineMode hides the raid-style party frames: pick when they show."] = "CineMode verbirgt die Gruppenrahmen im Schlachtzugsstil: Wähl, wann sie erscheinen."
L["CineMode hides your character's highlight: pick when it shows."] = "CineMode verbirgt die Hervorhebung deiner Figur: Wähl, wann sie erscheint."
L["CineMode hides these frames: pick which show, and when."] = "CineMode verbirgt diese Rahmen: Wähl, welche erscheinen, und wann."
L["Pick where chat bubbles show."] = "Wähl, wo Sprechblasen erscheinen."
L["Pick where and when each kind of bubble shows."] = "Wähl, wo und wann jede Art von Blase erscheint."
L["These bubbles show everywhere, in fights and out."] = "Diese Blasen erscheinen überall, im Kampf und außerhalb."
L["Cinematic draws its own bubbles for speech whose game bubble you can't see."] = "Cinematic zeichnet eigene Blasen für Gesagtes, dessen Spielblase du nicht sehen kannst."
L["Shows speech from someone off screen in a bubble low on the screen."] = "Zeigt Gesagtes von jemandem außerhalb des Bildschirms in einer Blase unten am Bildschirm."
L["Opens the Chat Bubble Style page: how off-screen bubbles look and where they show."] = "Öffnet die Seite Sprechblasenstil: wie Blasen von außerhalb des Bildschirms aussehen und wo sie erscheinen."
L["Shows emotes in the off-screen bubbles too, instead of in chat."] = "Zeigt Emotes auch in den Blasen von außerhalb, statt im Chat."
L["Moves bubbles at the very top of the screen down where you can read them."] = "Schiebt Blasen ganz oben am Bildschirm nach unten, wo du sie lesen kannst."
L["Small helpers for getting around the world."] = "Kleine Helfer für unterwegs in der Welt."
L["Turns all the Quality of Life helpers on or off."] = "Schaltet alle Komfort-Helfer ein oder aus."
L["Opens the character window when you drag gear out of your bags."] = "Öffnet das Charakterfenster, wenn du Ausrüstung aus deinen Taschen ziehst."
L["Adds a button to view the talents of someone you inspect."] = "Fügt eine Taste hinzu, um die Talente von jemandem anzusehen, den du betrachtest."
L["Adds a talent calculator button to your talents window to plan a build."] = "Fügt deinem Talentfenster eine Talentrechner-Taste hinzu, um eine Verteilung zu planen."
L["Moves game windows away from the left edge so your character stays in view."] = "Schiebt Spielfenster vom linken Rand weg, damit deine Figur im Blick bleibt."
L["Lets you drag the game's windows to move them."] = "Lässt dich die Fenster des Spiels ziehen, um sie zu verschieben."
L["Adds an icon to chat windows to copy their text."] = "Fügt Chatfenstern ein Symbol hinzu, um ihren Text zu kopieren."
L["Keep chat history"] = "Chatverlauf behalten"
L["Chat windows bring back their last lines after a reload or login."] = "Chatfenster holen nach einem Neuladen oder Einloggen ihre letzten Zeilen zurück."
L["Show the time on those lines"] = "Die Uhrzeit auf diesen Zeilen zeigen"
L["Puts the time at the start of brought-back lines."] = "Setzt die Uhrzeit an den Anfang zurückgeholter Zeilen."
L["Show XP left to level"] = "Fehlende EP bis zur Stufe zeigen"
L["Shows how much XP you still need for the next level."] = "Zeigt, wie viel EP du noch bis zur nächsten Stufe brauchst."
L["The camera zooms to the distance below when you log in or reload."] = "Die Kamera zoomt auf den Abstand unten, wenn du dich einloggst oder neu lädst."
L["The camera distance to start at."] = "Der Kameraabstand zum Start."
L["A button at the top of the screen that reloads the UI in one click."] = "Eine Taste oben am Bildschirm, die das UI mit einem Klick neu lädt."
L["Reopens the windows you had open after a reload."] = "Öffnet nach einem Neuladen die Fenster wieder, die du offen hattest."
L["Hides floating damage and healing numbers in CineMode out of combat."] = "Verbirgt schwebende Schadens- und Heilungszahlen in CineMode außerhalb des Kampfes."
L["Hides the red error text while you're fighting."] = "Verbirgt den roten Fehlertext, während du kämpfst."
L["Hides the red error text while you're out of combat."] = "Verbirgt den roten Fehlertext, solange du nicht im Kampf bist."
L["Turns the Hunter helpers on or off."] = "Schaltet die Jäger-Helfer ein oder aus."
L["Right-clicking an enemy uses Auto Shot when it's far enough away."] = "Ein Rechtsklick auf einen Gegner nutzt Automatischer Schuss, wenn er weit genug weg ist."
L["Moves the smallest ammo stack first after Clean Up Bags, so it's shot first."] = "Setzt nach Taschen aufräumen den kleinsten Munitionsstapel nach vorn, damit er zuerst verschossen wird."
L["Adds a Fill button at vendors that fills your quiver with ammo."] = "Fügt bei Händlern eine Taste Auffüllen hinzu, die deinen Köcher mit Munition füllt."
L["Keeps your pet frame up while your pet isn't happy."] = "Hält deinen Begleiterrahmen sichtbar, solange dein Begleiter nicht zufrieden ist."
L["The pet frame fades with the UI while a camera mode runs."] = "Der Begleiterrahmen blendet mit dem UI aus, solange ein Kameramodus läuft."
L["Move Questie's nameplate icons"] = "Namensplakettensymbole von Questie verschieben"
L["Moves Questie's quest icons beside the name, where Cinematic's quest mark goes."] = "Verschiebt die Questsymbole von Questie neben den Namen, wo das Questzeichen von Cinematic sitzt."
L["Move EnhanceQoL's nameplate quest marks"] = "Namensplaketten-Questzeichen von EnhanceQoL verschieben"
L["Keeps EnhanceQoL's quest marks up, beside the name where Cinematic's would go."] = "Hält die Questzeichen von EnhanceQoL sichtbar, neben dem Namen, wo die von Cinematic säßen."
L["Addon Support"] = "Addon-Unterstützung"
L["Settings for how Cinematic works with your other addons."] = "Einstellungen dafür, wie Cinematic mit deinen anderen Addons zusammenarbeitet."
L["Turns Cinematic's support for your other addons on or off."] = "Schaltet die Unterstützung von Cinematic für deine anderen Addons ein oder aus."
L["Right-click casts Fishing again and the Fishing cast bar hides, as this page says."] = "Rechtsklick wirkt erneut Angeln, und die Zauberleiste beim Angeln wird verborgen, wie diese Seite sagt."
L["Hides your cast bar while you're fishing."] = "Verbirgt deine Zauberleiste, während du angelst."
L["Right-click"] = "Rechtsklick"
L["Interact key"] = "Interaktionstaste"
L["Jump key"] = "Sprungtaste"
L["Middle mouse button"] = "Mittlere Maustaste"
L["Mouse button 4"] = "Maustaste 4"
L["Mouse button 5"] = "Maustaste 5"
L["With a fishing pole equipped, these cast Fishing when nothing is near."] = "Mit angelegter Angelrute wirken diese Angeln, wenn nichts in der Nähe ist."
L["Cast with"] = "Wirken mit"
L["How long after a cast ends before right-click casts again."] = "Wie lange nach dem Ende eines Zaubers, bis Rechtsklick wieder wirkt."
L["After a failed cast, right-click goes back to normal for this long."] = "Nach einem fehlgeschlagenen Zauber ist Rechtsklick so lange wieder normal."
L["Reel in with same key/click"] = "Mit derselben Taste/demselben Klick einholen"
L["Reels in with the same click or key you cast with."] = "Holt mit demselben Klick oder derselben Taste ein, mit der du ausgeworfen hast."
L["In gamepad mode, the button below casts Fishing like right-click does."] = "Im Gamepad-Modus wirkt die Taste unten Angeln wie ein Rechtsklick."
L["Sound"] = "Ton"
L["Louder while fishing"] = "Lauter beim Angeln"
L["Turns the game's volume up while your bobber is out, so you hear a bite."] = "Dreht die Lautstärke des Spiels auf, solange dein Schwimmer draußen ist, damit du einen Biss hörst."
L["Master volume"] = "Gesamtlautstärke"
L["The game's master volume while you fish."] = "Die Gesamtlautstärke des Spiels beim Angeln."
L["Sound effects volume"] = "Lautstärke der Soundeffekte"
L["Sound in the background too"] = "Ton auch im Hintergrund"
L["Keeps the game's sound playing in the background while you fish."] = "Lässt den Ton des Spiels beim Angeln auch im Hintergrund laufen."
