L["Every Vision at a glance; click a card to open it."] = "Alle Visions auf einen Blick; klicke auf eine Karte, um sie zu öffnen."
L["Turns all Visions on or off."] = "Schaltet alle Visions ein oder aus."
L["Breath Bar"] = "Atemleiste"
L["The breath bar and the game's other bars like it."] = "Die Atemleiste und die ähnlichen anderen Leisten des Spiels."
L["Turns this page's breath bar settings on or off."] = "Schaltet die Atemleisten-Einstellungen dieser Seite ein oder aus."
L["Hide the breath bar"] = "Atemleiste ausblenden"
L["Hides the breath bar and the game's other bars like it."] = "Blendet die Atemleiste und die ähnlichen anderen Leisten des Spiels aus."
L["Hide its text"] = "Ihren Text ausblenden"
L["Hides the word on the bar (Breath, Fatigue...), leaving the bar."] = "Blendet das Wort auf der Leiste aus (Atem, Erschöpfung …) und lässt die Leiste."
L["The bar's fill texture."] = "Die Fülltextur der Leiste."
L["The font of the word on the bar. (In Russian, Korean and Chinese it stays the game's.)"] = "Die Schriftart des Worts auf der Leiste. (Auf Russisch, Koreanisch und Chinesisch bleibt es die des Spiels.)"
L["Which swing timer bars show."] = "Welche Schwungtimerleisten erscheinen."
L["Turns this page's swing timer settings on or off."] = "Schaltet die Schwungtimer-Einstellungen dieser Seite ein oder aus."
L["Which bars show, and when they fade."] = "Welche Leisten erscheinen und wann sie ausblenden."
L["Shows only the bars for the weapons you're attacking with."] = "Zeigt nur die Leisten der Waffen, mit denen du angreifst."
L["How long a bar stays after you stop attacking."] = "Wie lange eine Leiste bleibt, nachdem du aufhörst anzugreifen."
L["Puts the ranged bar on top for this class."] = "Setzt die Fernkampfleiste für diese Klasse nach oben."
L["CineMode hides the Cooldown Manager: pick when it shows."] = "CineMode verbirgt den Abklingzeitenmanager: Wähl, wann er erscheint."
L["Turns this page's Cooldown Manager settings on or off."] = "Schaltet die Abklingzeitenmanager-Einstellungen dieser Seite ein oder aus."
L["CDM"] = "CDM"
L["Each bar's and spell's icons: when they show, numbers, keybinds and more."] = "Die Symbole jeder Leiste und jedes Zaubers: wann sie erscheinen, Zahlen, Tastenbelegungen und mehr."
L["Smart set, and how icons flash when a cooldown ends."] = "Smart-Einstellung, und wie Symbole aufblitzen, wenn eine Abklingzeit endet."
L["Cooldown Settings"] = "Abklingzeit-Einstellungen"
L["Open CDM"] = "CDM öffnen"
L["Opens the game's own Cooldown Manager settings."] = "Öffnet die Einstellungen des Abklingzeitenmanagers des Spiels."
L["Sets every spell in this group to this."] = "Setzt jeden Zauber dieser Gruppe darauf."
L["When this buff's icon or bar shows."] = "Wann das Symbol oder die Leiste dieses Stärkungszaubers erscheint."
L["Sets every buff in this group that you haven't set on its own."] = "Setzt jeden Stärkungszauber dieser Gruppe, den du nicht einzeln eingestellt hast."
L["The icon also waits until you have the resources to cast it."] = "Das Symbol wartet auch, bis du die Ressourcen zum Wirken hast."
L["Out of fights, the icon also shows once it's ready."] = "Außerhalb von Kämpfen erscheint das Symbol auch, sobald es bereit ist."
L["Game's option (on)"] = "Option des Spiels (an)"
L["Game's option (off)"] = "Option des Spiels (aus)"
L["Numbers"] = "Zahlen"
L["Countdown numbers on the icons."] = "Countdown-Zahlen auf den Symbolen."
L["Left to the game"] = "Dem Spiel überlassen"
L["Each spell's keybind on its icon."] = "Die Tastenbelegung jedes Zaubers auf seinem Symbol."
L["Use the spell's cooldown, not its buff"] = "Abklingzeit des Zaubers nutzen, nicht seinen Stärkungszauber"
L["Shows the spell's own cooldown instead of its buff or DoT."] = "Zeigt die eigene Abklingzeit des Zaubers statt seines Stärkungszaubers oder DoTs."
L["Same as bar (%s)"] = "Wie die Leiste (%s)"
L["Closes the gaps so the shown buffs sit centered."] = "Schließt die Lücken, damit die gezeigten Stärkungszauber zentriert sitzen."
L["Closes the gaps so the shown icons sit centered."] = "Schließt die Lücken, damit die gezeigten Symbole zentriert sitzen."
L["Keeps the Cooldown Manager up until every cooldown in this bar is ready."] = "Hält den Abklingzeitenmanager sichtbar, bis jede Abklingzeit dieser Leiste bereit ist."
L["Stacks and time left"] = "Stapel und Restzeit"
L["Shows stacks and time left on tracked buff icons."] = "Zeigt Stapel und Restzeit auf den Symbolen verfolgter Stärkungszauber."
L["Click for this bar's own settings."] = "Klicke für die eigenen Einstellungen dieser Leiste."
L["Click for this spell's own settings."] = "Klicke für die eigenen Einstellungen dieses Zaubers."
L["Sets spells you haven't set yourself based on what they cost."] = "Stellt Zauber, die du nicht selbst eingestellt hast, nach ihren Kosten ein."
L["Resets every icon setting to the active profile's."] = "Setzt jede Symboleinstellung auf die des aktiven Profils zurück."
L["Highlights mobs, NPCs and objects you still need for a quest."] = "Hebt Gegner, NPCs und Objekte hervor, die du noch für eine Quest brauchst."
L["Turns Quest Vision on or off."] = "Schaltet Quest Vision ein oder aus."
L["What shows of mobs and NPCs you still need for a quest."] = "Was von Gegnern und NPCs erscheint, die du noch für eine Quest brauchst."
L["Shows a gold ! beside the nameplates of quest mobs and NPCs."] = "Zeigt ein goldenes ! neben den Namensplaketten von Questgegnern und -NPCs."
L["Cinematic's wins"] = "Das von Cinematic gewinnt"
L["Questie's wins"] = "Das von Questie gewinnt"
L["Both show"] = "Beide erscheinen"
L["Which quest icon shows when both Cinematic and Questie mark the same unit."] = "Welches Questsymbol erscheint, wenn Cinematic und Questie dieselbe Einheit markieren."
L["Questie's icons"] = "Symbole von Questie"
L["The quest mark on friendly NPCs; click to pick another."] = "Das Questzeichen auf freundlichen NPCs; klicke, um ein anderes zu wählen."
L["The quest mark on enemies; click to pick another."] = "Das Questzeichen auf Gegnern; klicke, um ein anderes zu wählen."
L["A big button for the nearest tracked quest's usable item."] = "Eine große Taste für den benutzbaren Gegenstand der nächsten verfolgten Quest."
L["Fade if another addon competes"] = "Ausblenden, wenn ein anderes Addon konkurriert"
L["Hides this button when another addon shows one for the same item."] = "Verbirgt diese Taste, wenn ein anderes Addon eine für denselben Gegenstand zeigt."
L["The quest object in front of you glows gold."] = "Das Questobjekt vor dir leuchtet golden."
L["Hide object icons"] = "Objektsymbole ausblenden"
L["Hides the game's icon on the object your interact key would use."] = "Blendet das Symbol des Spiels auf dem Objekt aus, das deine Interaktionstaste nutzen würde."
L["Closes talking heads you've already seen."] = "Schließt sprechende Köpfe, die du schon gesehen hast."
L["NPC dialogue shows in a speech bubble and reply list instead of the game's windows."] = "NPC-Dialoge erscheinen in einer Sprechblase und Antwortliste statt in den Fenstern des Spiels."
L["Hides Cinematic's dialogue when another dialogue addon is running."] = "Verbirgt den Dialog von Cinematic, wenn ein anderes Dialog-Addon läuft."
L["Game's window with a controller"] = "Spielfenster mit Controller"
L["Uses the game's own dialogue windows in gamepad mode."] = "Nutzt im Gamepad-Modus die Dialogfenster des Spiels."
L["Where the speech bubble goes."] = "Wo die Sprechblase sitzt."
L["How far the bubble stays from the top of the screen."] = "Wie weit die Blase vom oberen Bildschirmrand entfernt bleibt."
L["Stops the camera drifting while you talk."] = "Hält die Kamera beim Gespräch vom Treiben ab."
L["What the bubble and card do while the camera moves."] = "Was Blase und Karte tun, während sich die Kamera bewegt."
L["The shop window opens where the talk was."] = "Das Händlerfenster öffnet sich dort, wo das Gespräch war."
L["Shows group loot rolls in a window instead of only in chat."] = "Zeigt Beutewürfe der Gruppe in einem Fenster statt nur im Chat."
L["Party/Dungeon"] = "Gruppe/Dungeon"
L["The rules while you're in a party: in a dungeon, a delve or out in the world."] = "Die Regeln, solange du in einer Gruppe bist: in einem Dungeon, einer Tiefe oder draußen in der Welt."
L["The rules while you're in a raid group."] = "Die Regeln, solange du in einer Schlachtzugsgruppe bist."
L["No panel; rolls show only in chat."] = "Kein Feld; Würfe erscheinen nur im Chat."
L["Shows a panel with the winner once the item's won."] = "Zeigt ein Feld mit dem Gewinner, sobald der Gegenstand gewonnen ist."
L["All Rolls"] = "Alle Würfe"
L["Whether items of this quality get a panel in the window."] = "Ob Gegenstände dieser Qualität ein Feld im Fenster bekommen."
L["Usable"] = "Benutzbar"
L["Only items you can use get a panel."] = "Nur Gegenstände, die du benutzen kannst, bekommen ein Feld."
L["Hide Uncounted"] = "Nicht Gezählte ausblenden"
L["Hides Greed and Transmog rolls once someone rolls Need."] = "Blendet Gier- und Transmog-Würfe aus, sobald jemand Bedarf würfelt."
L["Max Players"] = "Max. Spieler"
L["Each item lists at most this many players' rolls; click its panel to see everyone."] = "Jeder Gegenstand listet höchstens so viele Spielerwürfe; klicke sein Feld an, um alle zu sehen."
L["Separate window"] = "Eigenes Fenster"
L["Where the roll window shows: beside the game's roll frames or as its own window."] = "Wo das Würfelfenster erscheint: neben den Würfelrahmen des Spiels oder als eigenes Fenster."
L["Popup location"] = "Position des Fensters"
L["How many items the window shows at once; the oldest goes when a new one drops."] = "Wie viele Gegenstände das Fenster gleichzeitig zeigt; der älteste verschwindet, wenn ein neuer fällt."
L["Always show your roll"] = "Deinen Wurf immer zeigen"
L["Your own roll always shows on an item's panel."] = "Dein eigener Wurf erscheint immer im Feld eines Gegenstands."
L["Always show rolls I need"] = "Würfe, bei denen ich Bedarf würfle, immer zeigen"
L["Items you roll Need on always show everyone's rolls."] = "Gegenstände, auf die du Bedarf würfelst, zeigen immer die Würfe aller."
L["Shows the extra lines under an item's players, like who passed, in a party, raid or both."] = "Zeigt die zusätzlichen Zeilen unter den Spielern eines Gegenstands, etwa wer gepasst hat, in einer Gruppe, einem Schlachtzug oder beidem."
L["Show selected count"] = "Anzahl der Auswahl zeigen"
L["Stays hidden while another addon handles loot rolls."] = "Bleibt verborgen, solange ein anderes Addon Beutewürfe übernimmt."
L["In CineMode, shows the nameplates of players dueling near you so you can watch."] = "Zeigt in CineMode die Namensplaketten von Spielern, die sich in deiner Nähe duellieren, damit du zusehen kannst."
L["Shows an icon beside a duelist's nameplate while they're crowd controlled."] = "Zeigt ein Symbol neben der Namensplakette eines Duellanten, solange er unter Kontrolleffekten steht."
L["Instant spells"] = "Spontanzauber"
L["Shows a duelist's instant spells as icons beside their nameplate."] = "Zeigt die Spontanzauber eines Duellanten als Symbole neben seiner Namensplakette."
L["Spell names"] = "Zaubernamen"
L["The newest instant spell's name shows above its icon."] = "Der Name des neuesten Spontanzaubers erscheint über seinem Symbol."
L["Hides other players' duels while you're in one."] = "Verbirgt die Duelle anderer Spieler, solange du selbst in einem bist."
L["Shows a 30-second pretend duel between nearby players so you can see how it looks."] = "Zeigt ein gespieltes Duell von 30 Sekunden zwischen Spielern in der Nähe, damit du siehst, wie es aussieht."
L["Party and raid frames show only the members who need healing."] = "Gruppen- und Schlachtzugsrahmen zeigen nur die Mitglieder, die Heilung brauchen."
L["Turns Heal Vision on or off."] = "Schaltet Heal Vision ein oder aus."
L["Heal Vision out of fights while you have anything else targeted."] = "Heal Vision außerhalb von Kämpfen, solange du etwas anderes im Ziel hast."
L["Heal Vision everywhere."] = "Heal Vision überall."
L["Heal Vision's settings while you're a tank."] = "Die Einstellungen von Heal Vision, wenn du Tank bist."
L["Heal Vision's settings while you're a healer."] = "Die Einstellungen von Heal Vision, wenn du Heiler bist."
L["Heal Vision's settings while you're dealing damage."] = "Die Einstellungen von Heal Vision, wenn du Schaden machst."
L["Heal Vision on your party and raid frames."] = "Heal Vision auf deinen Gruppen- und Schlachtzugsrahmen."
L["Heal Vision on friendly nameplates."] = "Heal Vision auf freundlichen Namensplaketten."
L["Uses the Default tab's settings for this role."] = "Nutzt für diese Rolle die Einstellungen des Reiters Standard."
L["A tank shows once their health drops below this."] = "Ein Tank erscheint, sobald seine Gesundheit darunter fällt."
L["How much of a hidden tank still shows."] = "Wie viel von einem verborgenen Tank noch zu sehen ist."
L["A healer shows once their health drops below this."] = "Ein Heiler erscheint, sobald seine Gesundheit darunter fällt."
L["How much of a hidden healer still shows."] = "Wie viel von einem verborgenen Heiler noch zu sehen ist."
L["A damage dealer shows once their health drops below this."] = "Ein Schadensverursacher erscheint, sobald seine Gesundheit darunter fällt."
L["How much of a hidden damage dealer and the group titles still show."] = "Wie viel von einem verborgenen Schadensverursacher und den Gruppentiteln noch zu sehen ist."
L["A pet shows once its health drops below this."] = "Ein Begleiter erscheint, sobald seine Gesundheit darunter fällt."
L["How much of a hidden pet still shows."] = "Wie viel von einem verborgenen Begleiter noch zu sehen ist."
L["Fade range"] = "Einblendbereich"
L["Members fade in gradually as their health nears the line instead of popping in."] = "Mitglieder blenden nach und nach ein, wenn sich ihre Gesundheit der Grenze nähert, statt plötzlich aufzutauchen."
L["Your target always shows at least this much."] = "Dein Ziel ist immer mindestens so viel zu sehen."
L["The member under your mouse shows at least this much; 0% turns it off."] = "Das Mitglied unter deiner Maus ist mindestens so viel zu sehen; 0% heißt aus."
L["How much of offline members still shows."] = "Wie viel von Offline-Mitgliedern noch zu sehen ist."
L["How much of members out of your healing range still shows."] = "Wie viel von Mitgliedern außerhalb deiner Heilreichweite noch zu sehen ist."
L["Show while hidden"] = "Auch verborgen zeigen"
L["Shows ready check marks on hidden members too."] = "Zeigt Bereitschaftscheck-Haken auch auf verborgenen Mitgliedern."
L["Show only while hurt"] = "Nur zeigen, wenn verletzt"
L["A friendly player's name shows once they're hurt; the rest of their plate stays as it is."] = "Der Name eines freundlichen Spielers erscheint, sobald er verletzt ist; der Rest seiner Plakette bleibt, wie er ist."
L["The whole plate shows once they're hurt, as your nameplate style has it."] = "Die ganze Plakette erscheint, sobald er verletzt ist, wie es dein Namensplakettenstil vorsieht."
L["A group member's plate shows once their health drops below this."] = "Die Plakette eines Gruppenmitglieds erscheint, sobald seine Gesundheit darunter fällt."
L["How much of a hidden group member's plate still shows."] = "Wie viel von der Plakette eines verborgenen Gruppenmitglieds noch zu sehen ist."
L["Other players"] = "Andere Spieler"
L["Another player's plate shows once their health drops below this."] = "Die Plakette eines anderen Spielers erscheint, sobald seine Gesundheit darunter fällt."
L["How much of a hidden player's plate still shows."] = "Wie viel von der Plakette eines verborgenen Spielers noch zu sehen ist."
L["A pet's or minion's plate shows once its health drops below this."] = "Die Plakette eines Begleiters oder Dieners erscheint, sobald seine Gesundheit darunter fällt."
L["How much of a hidden pet's plate still shows."] = "Wie viel von der Plakette eines verborgenen Begleiters noch zu sehen ist."
L["Hold your Show hidden tooltips key to see a hidden tooltip in CineMode."] = "Halte deine Taste Ausgeblendete Tooltips zeigen, um in CineMode einen verborgenen Tooltip zu sehen."
L["Turns tooltip hiding in CineMode on or off."] = "Schaltet das Ausblenden von Tooltips in CineMode ein oder aus."
L["How long tooltips take to fade in and out."] = "Wie lange Tooltips zum Ein- und Ausblenden brauchen."
L["Hides tooltips once the mouse is still, or shows them only once it's still."] = "Verbirgt Tooltips, sobald die Maus ruht, oder zeigt sie erst, wenn sie ruht."
L["Pick where and when tooltips show in CineMode."] = "Wähl, wo und wann Tooltips in CineMode erscheinen."
L["Every tooltip, in the world and on the UI."] = "Jeder Tooltip, in der Welt und auf dem UI."
L["Pick which parts of the tooltip show and when."] = "Wähl, welche Teile des Tooltips erscheinen, und wann."
L["Where tooltips show: their usual corner or by your mouse."] = "Wo Tooltips erscheinen: in ihrer üblichen Ecke oder an deiner Maus."
L["How long you hover before the After column's parts show."] = "Wie lange du mit der Maus darüber bleibst, bevor die Teile der Spalte Nach erscheinen."
L["The box around the tooltip."] = "Der Kasten um den Tooltip."
L["Level (friends)"] = "Stufe (Freunde)"
L["The level line of players and NPCs you can't attack."] = "Die Stufenzeile von Spielern und NPCs, die du nicht angreifen kannst."
L["Level (enemies)"] = "Stufe (Gegner)"
L["The level line of players and NPCs you can attack."] = "Die Stufenzeile von Spielern und NPCs, die du angreifen kannst."
L["Right-click hints"] = "Rechtsklick-Hinweise"
L["The right-click hint lines on frames and items."] = "Die Rechtsklick-Hinweiszeilen auf Rahmen und Gegenständen."
L["Quest objective mobs"] = "Gegner für Questziele"
L["These tooltips show the After column's parts right away."] = "Diese Tooltips zeigen die Teile der Spalte Nach sofort."
L["No wait for"] = "Ohne Warten bei"
L["Filtered tooltips"] = "Gefilterte Tooltips"
L["Tooltips with these names never show in CineMode."] = "Tooltips mit diesen Namen erscheinen in CineMode nie."
L["Type a tooltip's top line as the game shows it."] = "Tippe die oberste Zeile eines Tooltips so, wie das Spiel sie zeigt."
L["Turns fading of other addons' frames in CineMode on or off."] = "Schaltet das Ausblenden der Rahmen anderer Addons in CineMode ein oder aus."
L["Show %s the whole time in CineMode.%s"] = "%s die ganze Zeit in CineMode zeigen.%s"
L["Switching an addon's support on or off counts after a reload. Reload now?"] = "Das Ein- oder Ausschalten der Unterstützung eines Addons gilt nach einem Neuladen. Jetzt neu laden?"
L["Turns Cinematic's support for this addon on or off after a reload."] = "Schaltet die Unterstützung von Cinematic für dieses Addon nach einem Neuladen ein oder aus."
L["Gives every row on this page the Default row's settings."] = "Gibt jeder Zeile dieser Seite die Einstellungen der Zeile Standard."
L["Smart Find looks for new addons' frames in the background for a while."] = "Intelligente Suche sucht eine Weile im Hintergrund nach Rahmen neuer Addons."
L["Looks for other addons' frames that nothing fades yet."] = "Sucht nach Rahmen anderer Addons, die noch nichts ausblendet."
L["Load all"] = "Alle laden"
L["Load"] = "Laden"
L["Puts it on the Loaded tab, under its addon, with the Default row's settings."] = "Setzt ihn auf den Reiter Geladen, unter sein Addon, mit den Einstellungen der Zeile Standard."
L["Hover over frames, then click Stop to add them to the list."] = "Fahr über Rahmen und klicke dann auf Stopp, um sie der Liste hinzuzufügen."
L["Type part of a frame's or addon's name to find it."] = "Tippe einen Teil des Namens eines Rahmens oder Addons, um ihn zu finden."
L["Turns CineMode on or off."] = "Schaltet CineMode ein oder aus."
L["Hides the whole UI but keeps the CineMode effects."] = "Verbirgt das ganze UI, behält aber die CineMode-Effekte."
L["Takes a screenshot with the UI hidden."] = "Macht einen Screenshot mit verborgenem UI."
L["Turns the visual effects on or off."] = "Schaltet die visuellen Effekte ein oder aus."
L["Shows or hides the letterbox bars."] = "Zeigt oder verbirgt die Kinobalken."
L["Hides the cursor until you move the mouse."] = "Verbirgt den Mauszeiger, bis du die Maus bewegst."
L["Reloads the UI."] = "Lädt das UI neu."
L["Opens or closes Cinematic's settings."] = "Öffnet oder schließt die Einstellungen von Cinematic."
L["Keyboard map"] = "Tastaturkarte"
L["Hold or tap to see what each key on your keyboard does."] = "Halten oder tippen, um zu sehen, was jede Taste deiner Tastatur tut."
L["Hold to open a wheel of all your wheels."] = "Halten, um ein Rad mit all deinen Rädern zu öffnen."
L["Hold to open a wheel of your cameras."] = "Halten, um ein Rad mit deinen Kameras zu öffnen."
L["Hold to open a wheel of the game's menu buttons."] = "Halten, um ein Rad mit den Menütasten des Spiels zu öffnen."
L["Hold to open a wheel of raid target markers."] = "Halten, um ein Rad mit Schlachtzugszielmarkierungen zu öffnen."
L["Hold to open a wheel of ground markers; only in a group."] = "Halten, um ein Rad mit Bodenmarkierungen zu öffnen; nur in einer Gruppe."
L["Hold to open a wheel that turns the visions on or off."] = "Halten, um ein Rad zu öffnen, das die Visions ein- oder ausschaltet."
L["Turns Damage Vision on or off (its Enable Page switch)."] = "Schaltet Damage Vision ein oder aus (sein Schalter Seite aktivieren)."
L["Turns Teleport Vision on or off (its Enable Page switch)."] = "Schaltet Teleport Vision ein oder aus (sein Schalter Seite aktivieren)."
L["Turns Emote Vision on or off (its Enable Page switch)."] = "Schaltet Emote Vision ein oder aus (sein Schalter Seite aktivieren)."
L["Turns Card Vision on or off (its Enable Page switch)."] = "Schaltet Card Vision ein oder aus (sein Schalter Seite aktivieren)."
L["Starts the AFK camera now."] = "Startet jetzt die AFK-Kamera."
L["Starts the cozy camera now."] = "Startet jetzt die gemütliche Kamera."
L["Starts the vista camera now."] = "Startet jetzt die Aussichtskamera."
L["Starts the fish camera now."] = "Startet jetzt die Angelkamera."
L["Starts the tele camera now."] = "Startet jetzt die Teleportkamera."
L["Starts or stops the RP walk camera."] = "Startet oder stoppt die RP-Gang-Kamera."
L["Starts or stops the auto-run camera."] = "Startet oder stoppt die Autolauf-Kamera."
L["Pretends you're dead for 30 seconds to test the death camera."] = "Tut 30 Sekunden so, als wärst du tot, um die Todeskamera zu testen."
L["Turns the Shoulder Cam on or off (its Enable Page switch)."] = "Schaltet die Schulterkamera ein oder aus (ihr Schalter Seite aktivieren)."
L["Stops whichever of Cinematic's cameras is running now, however it started."] = "Stoppt die gerade laufende Kamera von Cinematic, egal wie sie gestartet wurde."
L["Targets the last NPC who spoke near you."] = "Visiert den letzten NPC an, der in deiner Nähe gesprochen hat."
L["Scene keys"] = "Szenentasten"
L["Plays your scenes that use this key."] = "Spielt deine Szenen ab, die diese Taste nutzen."
L["Hold to see tooltips that are hidden."] = "Halten, um verborgene Tooltips zu sehen."
L["hidden"] = "verborgen"
L["Click, then press a key; right-click to clear."] = "Klicke, dann drück eine Taste; Rechtsklick zum Leeren."
L["Keys for Cinematic, the same as in the game's Key Bindings under AddOns."] = "Tasten für Cinematic, dieselben wie in der Tastaturbelegung des Spiels unter AddOns."
L["Key groups"] = "Tastengruppen"
L["New key group"] = "Neue Tastengruppe"
L["A key group of your own: name it, set its key and pick its frames."] = "Eine eigene Tastengruppe: Benenne sie, leg ihre Taste fest und wähl ihre Rahmen."
L["Deletes this group and its keys."] = "Löscht diese Gruppe und ihre Tasten."
L["Pick the frames this group's key shows and hides."] = "Wähl die Rahmen, die die Taste dieser Gruppe zeigt und verbirgt."
L["Key group %d"] = "Tastengruppe %d"
L["No frames yet: pick them on the right"] = "Noch keine Rahmen: Wähl sie rechts"
L["Pick frames (%d)"] = "Rahmen wählen (%d)"
L["Reset frame keys after a reload"] = "Rahmentasten nach einem Neuladen zurücksetzen"
L["Frames you showed or hid with their keys go back to normal after a reload."] = "Rahmen, die du mit ihren Tasten gezeigt oder verborgen hast, werden nach einem Neuladen wieder normal."
L["Back to their Show in rows"] = "Zurück zu ihren Zeilen Zeigen in"
L["A profile is a whole set of settings you can switch between."] = "Ein Profil ist ein kompletter Satz Einstellungen, zwischen denen du wechseln kannst."
L["Pick, add and share profiles."] = "Profile wählen, hinzufügen und teilen."
L["Change parts of the active profile."] = "Teile des aktiven Profils ändern."
L["This character keeps its own profile."] = "Dieser Charakter behält sein eigenes Profil."
L["Makes a copy of the active profile as your own."] = "Erstellt eine Kopie des aktiven Profils als dein eigenes."
L["Brings back an older copy of a profile."] = "Holt eine ältere Kopie eines Profils zurück."
L["Adds a profile someone shared with you."] = "Fügt ein Profil hinzu, das jemand mit dir geteilt hat."
L["Gives you the active profile as text to share."] = "Gibt dir das aktive Profil als Text zum Teilen."
L["Write what the active profile is for."] = "Schreib, wofür das aktive Profil ist."
L["Puts the active profile back to how you last saved it."] = "Setzt das aktive Profil auf deinen letzten Speicherstand zurück."
L["Saves the active profile as the point Reset goes back to."] = "Speichert das aktive Profil als den Stand, auf den Zurücksetzen zurückgeht."
L["Your own profile."] = "Dein eigenes Profil."
L["Customizing %s"] = "%s wird angepasst"
L["Customize %s"] = "%s anpassen"
L["Frames in the same group come up together when you mouse over any of them."] = "Rahmen derselben Gruppe kommen zusammen hervor, wenn du mit der Maus über einen davon fährst."
L["How long a frame stays after your mouse leaves it."] = "Wie lange ein Rahmen bleibt, nachdem deine Maus ihn verlässt."
