L["%s (%d of %d parts)"] = "%s (%d von %d Teilen)"
L["Which parts of this frame come up with this group."] = "Welche Teile dieses Rahmens mit dieser Gruppe hervorkommen."
L["When this group works: any time, in combat or out of combat."] = "Wann diese Gruppe wirkt: jederzeit, im Kampf oder außerhalb des Kampfes."
